if(indexof(scenename, 'scene_zen') == 0,                  set(global.scene_cat_result, 'zen'); );

for(set(i,0), i LT scene.count, inc(i),
	get_scene_category(get(scene[get(i)].name));
	copy(scene[get(i)].category, global.scene_cat_result);
);
set(global.categories_assigned, true);


if(skin_settings.thumbs != true, break(); );
if(global.categories_assigned != true, break(); );
if(xml.scene == null, break(); );
copy(_cat, scene[get(xml.scene)].category);
if(_cat == null, break(); );
if(global.current_thumb_category == get(_cat), break(); );
copy(global.current_thumb_category, get(_cat));

copy(_tw, skin_settings.thumbs_width);
copy(_th, skin_settings.thumbs_height);
copy(_tp, skin_settings.thumbs_padding);
calc(_xoffset, _tw + _tp);
calc(_xcenter, _xoffset * 0.5);

set(_pos, 0);
for(set(i,0), i LT thumbarray.length, inc(i),
	copy(_sname, thumbarray[get(i)].name);
	calc(_layername, 'skin_thumb_' + i);
	if(scene[get(_sname)].category == get(_cat),
		set(layer[get(_layername)].visible, true);
		set(layer[get(_layername)].enabled, true);
		calc(layer[get(_layername)].x, _tp + _pos * _xoffset);
		set(scene[get(_sname)].thumbx, calc(_tp + _pos * _xoffset + _xcenter));
		set(scene[get(_sname)].thumby, get(_tp));
		inc(_pos);
	,
		set(layer[get(_layername)].visible, false);
		set(layer[get(_layername)].enabled, false);
	);
);

calc(_barwidth, _xoffset * _pos + _tp);
set(layer[skin_thumbs].width, get(_barwidth));
skin_updatethumbsview(true);

if(scene.count == 0,
	trace('STARTUP: no scenes loaded!');
	break();
);

if(startscene == null OR startscene == '' OR !scene[get(startscene)],
	copy(startscene, scene[0].name);
);

assign_scene_categories();
delete(global.current_thumb_category);
loadscene(get(startscene), null, MERGE);

delayedcall(0.15,
	check_category_change();
	update_map_visibility();
	update_zoom_indicator();
);

if(xml.scene == null, break(); );
if(scene[get(xml.scene)].category == null, break(); );

if(scene[get(xml.scene)].category == 'street',

	set(layer[street_map_container].visible, true);
	set(plugin[radar_street].visible, true);
	set(layer[activespot_street].visible, true);
,

	set(layer[street_map_container].visible, true);
	set(plugin[radar_street].visible, false);
	set(layer[activespot_street].visible, false);
);

set(layer[street_map_container].visible, false);
set(layer[floorplans_container].visible, true);

set(plugin[radar_street].visible, false);
set(layer[activespot_street].visible, false);
set(layer[activespot_street].parent, null);
set(plugin[radar_street].parent, null);

set(plugin[radar_lab].visible, true);
set(layer[activespot_lab].visible, true);

set(layer[floorplans_container].visible, false);
set(layer[street_map_container].visible, true);

set(plugin[radar_lab].visible, false);
set(layer[activespot_lab].visible, false);
set(layer[activespot_lab].parent, null);
set(plugin[radar_lab].parent, null);

set(plugin[radar_street].visible, true);
set(layer[activespot_street].visible, true);
